// 通用技能模板（用于无数据的精灵作为后备）
function generateDefaultSkills(petType) {
  const mainType = Array.isArray(petType) ? petType[0] : petType;
  return { skills: [], builds: [], guide: [] };
}

function getPetSkillData(petName, petType) {
  if (PET_SKILLS_DB[petName]) return PET_SKILLS_DB[petName];
  return generateDefaultSkills(petType);
}
